func usage() {
	fmt.Fprintln(os.Stderr, "usage: lcheck [history.ndjson]")
	fmt.Fprintln(os.Stderr, "  reads the NDJSON event log from the file or stdin and prints")
	fmt.Fprintln(os.Stderr, "  a JSON verdict: {linearizable, failing_prefix, violated_edge}")
}

func main() {
	var in *os.File
	path := "-"
	if len(os.Args) > 1 {
		path = os.Args[1]
	}
	if path == "-" {
		in = os.Stdin
	} else {
		f, err := os.Open(path)
		if err != nil {
			fmt.Fprintln(os.Stderr, "lcheck:", err)
			os.Exit(2)
		}
		defer f.Close()
		in = f
	}

	ops, inits, err := ParseEvents(in)
	if err != nil {
		fmt.Fprintln(os.Stderr, "lcheck:", err)
		os.Exit(2)
	}

	res := Check(ops, inits)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(res); err != nil {
		fmt.Fprintln(os.Stderr, "lcheck:", err)
		os.Exit(2)
	}
	if !res.Linearizable {
		os.Exit(1)
	}
}
